fn draw_grid(dl: &mut DebugLines, dimension: SceneViewDimension) {
    let dim = 10_i32;
    for i in -dim..=dim {
        let value = i as f32;
        let primary = if i == 0 {
            Vec3::new(0.8, 0.1, 0.1)
        } else {
            Vec3::splat(0.25)
        };
        let secondary = if i == 0 {
            match dimension {
                SceneViewDimension::ThreeD => Vec3::new(0.1, 0.1, 0.8),
                SceneViewDimension::TwoD => Vec3::new(0.1, 0.8, 0.1),
            }
        } else {
            Vec3::splat(0.25)
        };
        match dimension {
            SceneViewDimension::ThreeD => {
                dl.line(
                    Vec3::new(value, 0.0, -(dim as f32)),
                    Vec3::new(value, 0.0, dim as f32),
                    primary,
                );
                dl.line(
                    Vec3::new(-(dim as f32), 0.0, value),
                    Vec3::new(dim as f32, 0.0, value),
                    secondary,
                );
            }
            SceneViewDimension::TwoD => {
                dl.line(
                    Vec3::new(value, -(dim as f32), 0.0),
                    Vec3::new(value, dim as f32, 0.0),
                    primary,
                );
                dl.line(
                    Vec3::new(-(dim as f32), value, 0.0),
                    Vec3::new(dim as f32, value, 0.0),
                    secondary,
                );
            }
        }
    }
    dl.line(Vec3::ZERO, Vec3::X * 2.0, Vec3::new(1.0, 0.0, 0.0));
    dl.line(Vec3::ZERO, Vec3::Y * 2.0, Vec3::new(0.0, 1.0, 0.0));
    if dimension == SceneViewDimension::ThreeD {
        dl.line(Vec3::ZERO, Vec3::Z * 2.0, Vec3::new(0.0, 0.0, 1.0));
    }
}
